from typing import List

def maximumOr(nums: List[int], k: int) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # Precompute prefix OR and suffix OR
    prefix_or = [0] * n
    suffix_or = [0] * n

    prefix_or[0] = nums[0]
    for i in range(1, n):
        prefix_or[i] = prefix_or[i-1] | nums[i]

    suffix_or[n-1] = nums[n-1]
    for i in range(n-2, -1, -1):
        suffix_or[i] = suffix_or[i+1] | nums[i]

    max_val = 0
    for i in range(n):
        # Apply k multiplications by 2 to nums[i]
        modified = nums[i] * (1 << k)

        if i == 0:
            total_or = modified | suffix_or[1] if n > 1 else modified
        elif i == n-1:
            total_or = prefix_or[n-2] | modified
        else:
            total_or = prefix_or[i-1] | modified | suffix_or[i+1]

        if total_or > max_val:
            max_val = total_or

    return max_val
