import heapq

def minimizeStringValue(s: str) -> str:
    n = len(s)
    cnt = [0] * 26
    for ch in s:
        if ch != '?':
            cnt[ord(ch) - ord('a')] += 1

    q_total = s.count('?')

    def min_cost(counts, q):
        h = list(counts)
        heapq.heapify(h)
        for _ in range(q):
            x = heapq.heappop(h)
            heapq.heappush(h, x + 1)
        return sum(x * (x - 1) // 2 for x in h)

    global_min = min_cost(cnt, q_total)

    result = list(s)
    remaining_q = q_total
    cur_cnt = cnt[:]

    for i in range(n):
        if result[i] != '?':
            cur_cnt[ord(result[i]) - ord('a')] += 1
            continue
        for c in range(26):
            cur_cnt[c] += 1
            if remaining_q == 1 or min_cost(cur_cnt, remaining_q - 1) == global_min:
                result[i] = chr(ord('a') + c)
                remaining_q -= 1
                break
            cur_cnt[c] -= 1
        else:
            result[i] = 'a'
            remaining_q -= 1

    return ''.join(result)
