def numberOfRightTriangles(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    m = len(grid)
    n = len(grid[0])

    # 預先計算每行和每列中 1 的數量
    row_ones = [0] * m
    col_ones = [0] * n

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                row_ones[i] += 1
                col_ones[j] += 1

    # 對於每個為 1 的位置 (i, j)：
    # 它可以作為右三角形的「直角頂點」
    # 此時，另外兩個點必須分別在同一行和同一列
    # 在同一行中，除了 (i, j) 之外，還有 (row_ones[i] - 1) 個 1
    # 在同一列中，除了 (i, j) 之外，還有 (col_ones[j] - 1) 個 1
    # 因此，以 (i, j) 為直角頂點的三角形數量 = (row_ones[i] - 1) * (col_ones[j] - 1)

    total = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                total += (row_ones[i] - 1) * (col_ones[j] - 1)

    return total

