def numberOfRightTriangles(grid: list[list[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    row_counts = [0] * cols
    col_counts = [0] * rows
    for r in range(rows):
        for c in range(cols):
            if grid[r][c]:
                row_counts[c] += 1
                col_counts[r] += 1
    ans = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c]:
                ans += (row_counts[c] - 1) * (col_counts[r] - 1)
    return ans
