def punishmentNumber(n: int) -> int:
    def can_partition(s: str, target: int) -> bool:
        # s is the string representation of i*i
        # We need to partition s into contiguous substrings whose sum equals target
        # Use recursion with memoization
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dfs(pos: int, current_sum: int) -> bool:
            if pos == len(s):
                return current_sum == target
            # Try all possible partitions starting at pos
            for end in range(pos + 1, len(s) + 1):
                part = int(s[pos:end])
                if current_sum + part > target:
                    break
                if dfs(end, current_sum + part):
                    return True
            return False

        return dfs(0, 0)

    result = 0
    for i in range(1, n + 1):
        sq = i * i
        s = str(sq)
        if can_partition(s, i):
            result += sq
    return result
